INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2657, 'Miếu bà chúa Xứ | Chùa bà Châu Đốc An Giang linh thiêng ở Núi Sam', 'mieu-ba-chua-xu', '
<p>Miếu bà chúa Xứ núi Sam ở Châu Đốc là một ngôi chùa bà linh thiêng bậc nhất miền Nam. Nơi đây mỗi năm đón hàng triệu du khách tham quan và cúng viếng. Chắc chắn sự linh thiêng của nó đã được chứng minh qua lượng du khách đông đảo quay lại hàng năm như thế. Hãy cùng Huynh Hieu Travel tìm hiểu về những nét đặc trưng của miếu bà chúa Xứ nhé!</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/cảnh-quan-tấp-nập-người-dân-cầu-khấn-ở-miếu-bà-chúa-xứ-1024x853.jpg" alt="Cảnh quan tấp nập người dân cấu khấn ở miếu bà chúa Xứ" class="wp-image-2715"/><figcaption>Cảnh quan tấp nập người dân cấu khấn ở miếu bà chúa Xứ</figcaption></figure>



<h2 class="wp-block-heading">Lịch sử</h2>



<p>Lịch sử miếu bà chúa Xứ cũng có nhiều giả thuyết khác nhau, nhưng chủ yếu vẫn có hai giả thuyết chính về nguồn gốc miếu bà chúa Xứ. Nhưng chắc chắn một điều là tượng bà trước đây mang giới tính Nam và được vẽ lại thành một tượng bà sau này.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/tượng-bà-chúa-xứ-1024x853.jpg" alt="Tượng bà chúa Xứ" class="wp-image-2762"/><figcaption>Tượng bà chúa Xứ</figcaption></figure>



<h3 class="wp-block-heading">Giả thuyết 1 về tượng bà chúa Xứ</h3>



<p>Trước đây, một vị hoàng tử Ấn Độ tiến vào Việt Nam đã mang theo một tượng thần <a rel="noreferrer noopener nofollow" aria-label="Vishnu  (mở trong tab mới)" href="https://vi.wikipedia.org/wiki/Vishnu" target="_blank">Vishnu </a>đến đây. Và một thời gian, tượng thần bị bỏ lại trên đỉnh núi Sam nhiều năm và đần bị phai mờ hình dáng bên ngoài. Người dân sau này phát hiện ra và đã tô điểm lại và trở thành một tượng phật Bà. Nó mang ảnh hưởng văn hóa Óc Eo từ thế kỷ thứ VI.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/kiến-trúc-miếu-bà-chúa-xứ-1024x853.jpg" alt="Kiến trúc miếu bà chúa Xứ" class="wp-image-2736"/><figcaption>Kiến trúc miếu bà chúa Xứ</figcaption></figure>



<h3 class="wp-block-heading" id="mce_6">Giả thuyết 2 về tượng Bà chúa Xứ</h3>



<p>Một số giả thuyết khác cho rằng Tượng bà chúa Xứ là một tượng Phật của người Khmer bỏ lại sau khi di chuyển bởi sự chiếm đóng của người Việt. Sau này một số người đã tô điểm thêm khiến bức tượng trở thành bà chúa Xứ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/kiến-trúc-tuyệt-vời-miếu-bà-chúa-xứ-1024x853.jpg" alt="Kiến trúc tuyệt vời miếu bà chúa Xứ" class="wp-image-2737"/><figcaption>Kiến trúc tuyệt vời</figcaption></figure>



<h2 class="wp-block-heading">Sự tích miếu bà chúa Xứ núi Sam</h2>



<p>Khi bị bỏ lại trên đỉnh núi Sam, tượng bà chúa Xứ cũng khá linh thiêng nhưng không được nhiều người biết đến. Phải đến lúc ông <a rel="noreferrer noopener nofollow" aria-label="Thoại Ngọc Hầu (mở trong tab mới)" href="https://vi.wikipedia.org/wiki/Tho%E1%BA%A1i_Ng%E1%BB%8Dc_H%E1%BA%A7u" target="_blank">Thoại Ngọc Hầu</a> tuân lệnh chúa Nguyễn về xây dựng công trình đê điều ngăn lũ. Bạn đầu, ông cử nhiều dân chúng và thợ xây bắt đầu xây dựng những nền mống đầu tiên, nhưng cứ xây đến đâu lại gặp sự cố sập đến đó.&nbsp;</p>



<p>Sau đó, ông đã nằm mơ thấy bà chúa Xứ báo mộng là phải thỉnh bà xuống núi và xây dựng ngôi miếu để bà giúp sức xây dựng đê điều. Khi ấy ông đã cho làm lễ lớn, cử 9 chàng trai lực lưỡng đón bà xuống. Nhưng lạ thay, pho tượng đá như có sức nặng nghìn cân, 9 chàng trai lực lưỡng sáu múi cũng không thể khiêng nổi tảng đá lên.</p>



<p>Lúc ấy, bà chúa Xứ lại báo mộng với ông Thoại Ngọc Hầu rằng phải cho 9 cô gái đồng trinh thỉnh thì mới đem tượng bà xuống núi được. Quả nhiên, ngày hôm sau khi 9 cô gái đồng trinh mang tượng bà đi thì tượng trở nên nhẹ nhàng hơn rất nhiều.&nbsp;</p>



<p>Lúc ấy, nơi đây chỉ là ngôi miếu gỗ đơn sơ. Sau này, với nhiều lần trùng tu khác nhau, ngôi miếu dần trở nên khang trang và rộng lớn với kiến trúc độc đáo. Chỉ riêng tượng bà chúa Xứ vẫn như xưa.</p>



<h2 class="wp-block-heading">Kiến trúc</h2>



<p>Từ ngôi nhà gỗ vách lá ngày xưa, hiện nay miếu bà chúa Xứ trở thành một ngôi miếu lộng lẫy với nét kiến trúc mang đậm văn hóa phương Đông. Nhìn từ xa như một cung điện lung linh, lộng lẫy.</p>



<p>Sau đây là những bức vẽ thể hiện một số kiến trúc trên tường ở miếu Bà chúa Xứ</p>



<ul class="wp-block-gallery columns-3 is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex"><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1024" height="842" src="https://media.huynhhieutravel.com/bức-tranh-bệ-đá-bà-chúa-xứ-đỉnh-núi-sam-được-vẽ-trên-tường-miếu-bà-chúa-xứ-1024x842.jpg" alt="Bức tranh bệ đá chúa xứ đỉnh núi Sam được vẽ trên tường miếu bà chúa Xứ" data-id="2702" data-link="https://huynhhieutravel.com/buc-tranh-be-da-ba-chua-xu-dinh-nui-sam-duoc-ve-tren-tuong-mieu-ba-chua-xu/" class="wp-image-2702"/><figcaption>Bức tranh bệ đá chúa xứ đỉnh núi Sam được vẽ trên tường</figcaption></figure></li><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1024" height="826" src="https://media.huynhhieutravel.com/bức-tranh-đình-vĩnh-ngươn-được-vẽ-trên-tường-miếu-bà-chúa-xứ-1024x826.jpg" alt="Bức tranh đình Vĩnh Ngươn được vẽ trên tường miếu bà chúa Xứ" data-id="2708" data-link="https://huynhhieutravel.com/buc-tranh-dinh-vinh-nguon-duoc-ve-tren-tuong-mieu-ba-chua-xu/" class="wp-image-2708"/><figcaption>Bức tranh đình Vĩnh Ngươn được vẽ trên tường</figcaption></figure></li><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1024" height="870" src="https://media.huynhhieutravel.com/bức-tranh-đình-thần-vĩnh-tế-trên-tường-miếu-bà-chúa-xứ-1024x870.jpg" alt="Bức tranh đình thần Vĩnh Tế được vẽ trên tường miếu bà chúa Xứ" data-id="2707" data-link="https://huynhhieutravel.com/buc-tranh-dinh-than-vinh-te-tren-tuong-mieu-ba-chua-xu/" class="wp-image-2707"/><figcaption>Bức tranh đình thần Vĩnh Tế được vẽ trên tường</figcaption></figure></li><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1024" height="840" src="https://media.huynhhieutravel.com/bức-tranh-đình-thần-châu-phú-được-vẽ-trên-tường-miếu-bà-chúa-xứ-1024x840.jpg" alt="Bức tranh đình thần Châu Phú được vẽ trên tường miếu bà chúa Xứ" data-id="2706" data-link="https